export type Lang = "es" | "en" | "de" | "it" | "nl" | "ru" | "uk";

export interface RouteDay {
  title: Record<Lang, string>;
  text: Record<Lang, string>;
  photoSlot: string;
  image?: string;
  /** Author · licence · source, for photos that require attribution (CC BY / BY-SA). */
  imageCredit?: string;
  imageCreditUrl?: string;
  altText?: Record<Lang, string>;
}

export interface RouteTip {
  tip: Record<Lang, string>;
}

export interface RouteContent {
  slug: string;
  metaTitle: Record<Lang, string>;
  metaDescription: Record<Lang, string>;
  heroTitle: Record<Lang, string>;
  heroSubtitle: Record<Lang, string>;
  heroImage?: string;
  heroImageCredit?: string;
  heroImageCreditUrl?: string;
  /** Placeholder id for the hero photo while no image file exists yet. */
  heroPhotoSlot?: string;
  /** Overrides ROUTE_BYLINE for guides we have not driven ourselves as one trip. */
  byline?: Record<Lang, string>;
  intro: Record<Lang, string>;
  days: RouteDay[];
  tips: RouteTip[];
  ctaText: Record<Lang, string>;
  ctaButton: Record<Lang, string>;
}

